(7272371, 1132029, 86447, '<td valign="top">8 from me... love the balloon echoing her clothing.</td>', '8 from me... love the balloon echoing her clothing.', '2014-10-11 20:23:25.000000', NULL, 1),
(7272372, 1132017, 124982, '<td valign="top">Such a minimal and simple image. I say this not as an offense, but as a compliment because it''s a startlingly appealing image. Both in terms of it''s composition and processing. Normally such a severe crop would be a faux pas, but here it just works...and I don''t know why. Lovely shot@!</td>', 'Such a minimal and simple image. I say this not as an offense, but as a compliment because it''s a startlingly appealing image. Both in terms of it''s composition and processing. Normally such a severe crop would be a faux pas, but here it just works...and I don''t know why. Lovely shot@!', '2014-10-11 20:23:34.000000', NULL, 1),
(7272373, 1131736, 86447, '<td valign="top">8 from me... love that the boats lead us across the image to the man.</td>', '8 from me... love that the boats lead us across the image to the man.', '2014-10-11 20:23:43.000000', NULL, 1),
(7272374, 1131714, 86447, '<td valign="top">8 from me... rare for me to score that highly with a "blurry image"... but... I love this!  It speaks to me.  *grin*</td>', '8 from me... rare for me to score that highly with a "blurry image"... but... I love this!  It speaks to me.  *grin*', '2014-10-11 20:24:08.000000', NULL, 1),
(7272375, 1131596, 86447, '<td valign="top">8 from me.   I love the graphics-likeness of this.</td>', '8 from me.   I love the graphics-likeness of this.', '2014-10-11 20:24:22.000000', NULL, 1),
(7272376, 1131952, 124982, '<td valign="top">A lovely intimate capture! No artifice, just real life unobscured by manipulation. Well done!</td>', 'A lovely intimate capture! No artifice, just real life unobscured by manipulation. Well done!', '2014-10-11 20:24:38.000000', NULL, 1),
(7272377, 1131856, 86447, '<td valign="top">8 from me.   Looks like a scratched up photo from the 70s... WELL DONE!</td>', '8 from me.   Looks like a scratched up photo from the 70s... WELL DONE!', '2014-10-11 20:24:40.000000', NULL, 1),
