(7272399, 1131992, 86447, '<td valign="top">7 from me.   Quirky and fun.</td>', '7 from me.   Quirky and fun.', '2014-10-11 20:29:32.000000', NULL, 1),
(7272400, 1131508, 86447, '<td valign="top">7 from me... great focus and blur!</td>', '7 from me... great focus and blur!', '2014-10-11 20:29:44.000000', NULL, 1),
