(7272402, 1131819, 86447, '<td valign="top">7 from me... you''ve taken the humanness out of the scene by chopping off her head.  I love it.   It makes it so much more interesting.</td>', '7 from me... you''ve taken the humanness out of the scene by chopping off her head.  I love it.   It makes it so much more interesting.', '2014-10-11 20:30:27.000000', NULL, 1),
(7272403, 1131880, 86447, '<td valign="top">Ben??  7</td>', 'Ben??  7', '2014-10-11 20:30:32.000000', NULL, 1),
(7272404, 1131594, 86447, '<td valign="top">7 from me... Oddly interesting.</td>', '7 from me... Oddly interesting.', '2014-10-11 20:30:43.000000', NULL, 1),
(7272405, 1131986, 86447, '<td valign="top">7 from me... peaceful and calm.</td>', '7 from me... peaceful and calm.', '2014-10-11 20:30:55.000000', NULL, 1),
(7272407, 1131941, 86447, '<td valign="top">7 from me.   I wish her feet were more relaxed... but... I love the rest.</td>', '7 from me.   I wish her feet were more relaxed... but... I love the rest.', '2014-10-11 20:31:13.000000', NULL, 1),
(7272408, 1131526, 86447, '<td valign="top">7 from me.  I like the simpleness.</td>', '7 from me.  I like the simpleness.', '2014-10-11 20:31:32.000000', NULL, 1),
(7272409, 1131848, 86447, '<td valign="top">7 from me.   Gorgeously simple and stark, yet... so MUCH to see.</td>', '7 from me.   Gorgeously simple and stark, yet... so MUCH to see.', '2014-10-11 20:31:59.000000', NULL, 1),
(7272410, 1131947, 86447, '<td valign="top">7 from me.  And... I have no idea why!  LOL!  It just makes me interested.</td>', '7 from me.  And... I have no idea why!  LOL!  It just makes me interested.', '2014-10-11 20:32:23.000000', NULL, 1),
(7272412, 1131714, 124982, '<td valign="top">Very unconventional composition with the subject being cramped into the corner of the frame. It actually works here, as it gives space for the viewer to gaze out over the water to the skyline in the background. Wonder if this would''ve benefited from a warmer, more orange toning than the sepia?</td>', 'Very unconventional composition with the subject being cramped into the corner of the frame. It actually works here, as it gives space for the viewer to gaze out over the water to the skyline in the background. Wonder if this would''ve benefited from a warmer, more orange toning than the sepia?', '2014-10-11 20:34:51.000000', NULL, 1),
(7272413, 1131856, 124982, '<td valign="top">Lovely lighting, and nice use of the texture plate. It''s like the sun speckles are dancing across the frame.</td>', 'Lovely lighting, and nice use of the texture plate. It''s like the sun speckles are dancing across the frame.', '2014-10-11 20:35:13.000000', NULL, 1),
(7272414, 1131968, 124982, '<td valign="top">Some lovely light here, and a very pleasing composition! Nice use of the fence as a leading line. A little heavy handed with the processing for my liking though which robs the image of the serene, peaceful ambiance that is trying to come through.</td>', 'Some lovely light here, and a very pleasing composition! Nice use of the fence as a leading line. A little heavy handed with the processing for my liking though which robs the image of the serene, peaceful ambiance that is trying to come through.', '2014-10-11 20:37:26.000000', NULL, 1),
(7272415, 1132030, 124982, '<td valign="top">you''ve really managed to capture the essence of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=75618" rel="nofollow" target="_blank">odriew</a> with the way in which you have captured the light and let the warm glow infuse everything. Well done!</td>', 'you''ve really managed to capture the essence of  odriew with the way in which you have captured the light and let the warm glow infuse everything. Well done!', '2014-10-11 20:38:26.000000', NULL, 1),
(7272416, 1131508, 124982, '<td valign="top">A nice, soft portrait with some lovely even lighting! A little strong on the blur/glow effect, but that''s a personal taste.</td>', 'A nice, soft portrait with some lovely even lighting! A little strong on the blur/glow effect, but that''s a personal taste.', '2014-10-11 20:39:39.000000', NULL, 1),
(7272417, 1131716, 124982, '<td valign="top">Really like the vintage feel to the processing, using some blues in the shadows is a great technique! Wish there was smidge more light on her face though which is a little too dark for me.</td>', 'Really like the vintage feel to the processing, using some blues in the shadows is a great technique! Wish there was smidge more light on her face though which is a little too dark for me.', '2014-10-11 20:41:05.000000', NULL, 1),
(7272419, 1131736, 124982, '<td valign="top">Fantastic capture!! Really wonderful shot of daily living without manipulating the image. Normally, having a subject so close to the edge of the frame and moving/looking out of the frame is frowned upon, compositionally, but here it works. Give the shot a sense of movement and also mystique. Very nice light and processing, too.</td>', 'Fantastic capture!! Really wonderful shot of daily living without manipulating the image. Normally, having a subject so close to the edge of the frame and moving/looking out of the frame is frowned upon, compositionally, but here it works. Give the shot a sense of movement and also mystique. Very nice light and processing, too.', '2014-10-11 20:43:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7272420, 1132018, 124982, '<td valign="top">Is that a chunk of meat she''s about to eat?!! Meat on a stick!! Awesome, never seen that! Curiosity aside, I really do like the light and soft processing. Particularly the beautiful, prominent highlights in her hair.</td>', 'Is that a chunk of meat she''s about to eat?!! Meat on a stick!! Awesome, never seen that! Curiosity aside, I really do like the light and soft processing. Particularly the beautiful, prominent highlights in her hair.', '2014-10-11 20:45:13.000000', NULL, 1),
(7272421, 1131927, 124982, '<td valign="top">Soft and dreamy capture! A lovely contrast to the hard work the fishermen are about to engage in.</td>', 'Soft and dreamy capture! A lovely contrast to the hard work the fishermen are about to engage in.', '2014-10-11 20:46:09.000000', NULL, 1),
(7272424, 1131970, 124982, '<td valign="top">Lovely lighting and sillouetting of the birds! Great timing to catch all three like that. A little heavy handed on the texture overlay, maybe?</td>', 'Lovely lighting and sillouetting of the birds! Great timing to catch all three like that. A little heavy handed on the texture overlay, maybe?', '2014-10-11 20:57:16.000000', NULL, 1),
(7272425, 1131503, 124982, '<td valign="top">I was just admiring the warm light and whoa, there''s a guy in the mirror! Been looking at the image for a good 30seconds before I even saw him. What a great surprise! Nice intriguing little point of interest...really ups the impact of the photo! Smartly done. Bumping vote.</td>', 'I was just admiring the warm light and whoa, there''s a guy in the mirror! Been looking at the image for a good 30seconds before I even saw him. What a great surprise! Nice intriguing little point of interest...really ups the impact of the photo! Smartly done. Bumping vote.', '2014-10-11 20:59:51.000000', NULL, 1),
(7272426, 1132005, 124982, '<td valign="top">I absolutely love the unconventional angle to this shot! Really adds an extra layer of interest for me. The sun peaking through the side of the tree is another nice little touch! Overall, a pleasing composition, gently processed and visually appealing. Bumping my previous vote.</td>', 'I absolutely love the unconventional angle to this shot! Really adds an extra layer of interest for me. The sun peaking through the side of the tree is another nice little touch! Overall, a pleasing composition, gently processed and visually appealing. Bumping my previous vote.', '2014-10-11 21:04:14.000000', NULL, 1),
(7272430, 1131526, 124982, '<td valign="top">I''m such a fan of minimal shots like this. No over-production of the image, no props, just simple slices of nature at its finest. Such a delicate little image, wonderfully supported by the subtle processing. Quite beautiful. Bumping my earlier score.</td>', 'I''m such a fan of minimal shots like this. No over-production of the image, no props, just simple slices of nature at its finest. Such a delicate little image, wonderfully supported by the subtle processing. Quite beautiful. Bumping my earlier score.', '2014-10-11 21:24:09.000000', NULL, 1),
(7272432, 1131969, 124982, '<td valign="top">Soft and tender processing makes for a delightfully elegant portrait. Like how you lowered the contrast by shifting the blacks to the right...but wonder how this would look if you added some color (blues/magentas) into the shadows?</td>', 'Soft and tender processing makes for a delightfully elegant portrait. Like how you lowered the contrast by shifting the blacks to the right...but wonder how this would look if you added some color (blues/magentas) into the shadows?', '2014-10-11 21:27:23.000000', NULL, 1),
(7272433, 1131995, 124982, '<td valign="top">An ominous portent of things to come! Delightfully scary!</td>', 'An ominous portent of things to come! Delightfully scary!', '2014-10-11 21:29:41.000000', NULL, 1),
(7272434, 1131819, 124982, '<td valign="top">Reminds me of a spot in London...can''t recall the name right now. Lovely hill overlooking the river Thames. Perfect people-watching location! Really interesting composition with the man with the balloons and lady on the left with her back to us.</td>', 'Reminds me of a spot in London...can''t recall the name right now. Lovely hill overlooking the river Thames. Perfect people-watching location! Really interesting composition with the man with the balloons and lady on the left with her back to us.', '2014-10-11 21:31:58.000000', NULL, 1),
(7272435, 1131753, 124982, '<td valign="top">A lovely, private moment captured.</td>', 'A lovely, private moment captured.', '2014-10-11 21:35:40.000000', NULL, 1),
(7272436, 1131997, 124982, '<td valign="top">Really fun shot! Just love the splashes of color from the balloons and the band of hazy sunlight cutting across the frame.</td>', 'Really fun shot! Just love the splashes of color from the balloons and the band of hazy sunlight cutting across the frame.', '2014-10-11 21:37:10.000000', NULL, 1),
(7272437, 1131871, 124982, '<td valign="top">Very interesting focal planes here...very tilt-shifty! Quite unique! Wish the bright spot on the top right was a little less over-powering, but hard to do given the conditions you were shooting under!</td>', 'Very interesting focal planes here...very tilt-shifty! Quite unique! Wish the bright spot on the top right was a little less over-powering, but hard to do given the conditions you were shooting under!', '2014-10-11 21:39:18.000000', NULL, 1),
(7272438, 1131965, 124982, '<td valign="top">lovely contrast between the soft, delicate nature of the flower and the hard, unyielding backdrop of bricks and mortar. The little splash of pink makes for a lovely accented focal point.</td>', 'lovely contrast between the soft, delicate nature of the flower and the hard, unyielding backdrop of bricks and mortar. The little splash of pink makes for a lovely accented focal point.', '2014-10-11 21:41:24.000000', NULL, 1),
(7272446, 1131930, 13077, '<td valign="top">I don''t see the influence by odriew''s work here, to be honest. While it''s not bad - the light on the leaves near the water is good - I think a either a tighter or looser composition would have made better use of the scene. Maybe to include more of the water and just that first layer of yellowing leaves above it?</td>', 'I don''t see the influence by odriew''s work here, to be honest. While it''s not bad - the light on the leaves near the water is good - I think a either a tighter or looser composition would have made better use of the scene. Maybe to include more of the water and just that first layer of yellowing leaves above it?', '2014-10-11 21:48:39.000000', NULL, 1),
(7272447, 1131857, 50864, '<td valign="top">Wonderfully captured and processed. Top pick</td>', 'Wonderfully captured and processed. Top pick', '2014-10-11 21:49:28.000000', NULL, 1),
(7272448, 1131922, 13077, '<td valign="top">I like the unusual angle and the processing here, and nicely framed using their legs, but the background is distracting to me.</td>', 'I like the unusual angle and the processing here, and nicely framed using their legs, but the background is distracting to me.', '2014-10-11 21:49:39.000000', NULL, 1),
(7272449, 1131883, 13077, '<td valign="top">Nice title - play on words. I don''t really see his style coming through in this one at all, though.</td>', 'Nice title - play on words. I don''t really see his style coming through in this one at all, though.', '2014-10-11 21:50:30.000000', NULL, 1),
(7272450, 1131927, 13077, '<td valign="top">Nice - simple but a lot going on out there in the water, and the bird is an excellent addition to this composition.</td>', 'Nice - simple but a lot going on out there in the water, and the bird is an excellent addition to this composition.', '2014-10-11 21:51:09.000000', NULL, 1),
(7272451, 1131966, 13077, '<td valign="top">I like the atmosphere of this - early fall dusk or dawn, out in the park with the dog. Nicely composed and well processed, and I like that they are both intently watching something out of frame. It conveys a mysterious aspect I saw in a lot of odriew''s work.</td>', 'I like the atmosphere of this - early fall dusk or dawn, out in the park with the dog. Nicely composed and well processed, and I like that they are both intently watching something out of frame. It conveys a mysterious aspect I saw in a lot of odriew''s work.', '2014-10-11 21:52:26.000000', NULL, 1),
(7272452, 1131791, 13077, '<td valign="top">Is it a pinhole shot? I like the muted colors and the composition, but I would really like it if someone were on the bridge.</td>', 'Is it a pinhole shot? I like the muted colors and the composition, but I would really like it if someone were on the bridge.', '2014-10-11 21:53:32.000000', NULL, 1),
(7272453, 1131891, 13077, '<td valign="top">Nicely panned to keep sharpness in most of the car, and the guy driving it. I like the processing as well.</td>', 'Nicely panned to keep sharpness in most of the car, and the guy driving it. I like the processing as well.', '2014-10-11 21:53:56.000000', NULL, 1),
(7272454, 1131713, 13077, '<td valign="top">Excellent - the wheelbarrow and the water bottle being in the foreground adds a lot of dramatic shapes, colors and textures, and then the lady''s pose and the tranquil environment just make it a happy kind of photo, but with an air of suspense and curiosity.</td>', 'Excellent - the wheelbarrow and the water bottle being in the foreground adds a lot of dramatic shapes, colors and textures, and then the lady''s pose and the tranquil environment just make it a happy kind of photo, but with an air of suspense and curiosity.', '2014-10-11 21:55:09.000000', NULL, 1),
(7272455, 1131714, 13077, '<td valign="top">I like the composition, but I think the motion blur is a little too heavy here.</td>', 'I like the composition, but I think the motion blur is a little too heavy here.', '2014-10-11 21:55:32.000000', NULL, 1),
(7272456, 1131947, 50864, '<td valign="top">Beautiful soft look. I''m enjoying that  I can''t quite make out what is behind the panels.</td>', 'Beautiful soft look. I''m enjoying that  I can''t quite make out what is behind the panels.', '2014-10-11 21:56:39.000000', NULL, 1),
(7272457, 1131987, 13077, '<td valign="top">It looks like a nice scene, but the positioning of the boy makes him get lost in the quite busy background. I feel like there were some cleaner, more compelling compositions to be found at this location if you had kept working it.</td>', 'It looks like a nice scene, but the positioning of the boy makes him get lost in the quite busy background. I feel like there were some cleaner, more compelling compositions to be found at this location if you had kept working it.', '2014-10-11 21:56:50.000000', NULL, 1),
(7272458, 1131871, 13077, '<td valign="top">Nice dramatic light and I like the tilt/shift focus effect. Well composed and exposed, too.</td>', 'Nice dramatic light and I like the tilt/shift focus effect. Well composed and exposed, too.', '2014-10-11 21:57:21.000000', NULL, 1),
(7272460, 1131933, 50864, '<td valign="top">I think this is my favorite in the challenge. Really love the smeared left side and the perfectly captured little guy behind the fence. 10</td>', 'I think this is my favorite in the challenge. Really love the smeared left side and the perfectly captured little guy behind the fence. 10', '2014-10-11 21:59:32.000000', NULL, 1),
(7272461, 1131943, 13077, '<td valign="top">Interesting soft-focus/low-key combination - I feel like a partial soft-focus technique where at least some of the flowers are in focus might have served this one better, though.</td>', 'Interesting soft-focus/low-key combination - I feel like a partial soft-focus technique where at least some of the flowers are in focus might have served this one better, though.', '2014-10-11 22:00:40.000000', NULL, 1),
(7272462, 1131910, 13077, '<td valign="top">Great observation to make use of these exceptional shadows. Very well composed and processed.</td>', 'Great observation to make use of these exceptional shadows. Very well composed and processed.', '2014-10-11 22:01:41.000000', NULL, 1),
(7272463, 1132038, 50864, '<td valign="top">The little leave on the end of the twig are perfect in this beautiful image. Top pick.</td>', 'The little leave on the end of the twig are perfect in this beautiful image. Top pick.', '2014-10-11 22:02:12.000000', NULL, 1),
(7272464, 1131691, 13077, '<td valign="top">Interesting concept.</td>', 'Interesting concept.', '2014-10-11 22:02:19.000000', NULL, 1),
(7272465, 1131995, 13077, '<td valign="top">I''ll have to take your word for it. Seems plausible to imagine it that way, and it''s fairly attractive overall.</td>', 'I''ll have to take your word for it. Seems plausible to imagine it that way, and it''s fairly attractive overall.', '2014-10-11 22:03:05.000000', NULL, 1),
(7272466, 1131924, 13077, '<td valign="top">Very good light here. I like the softness and the composition, and the processing is well done.</td>', 'Very good light here. I like the softness and the composition, and the processing is well done.', '2014-10-11 22:03:50.000000', NULL, 1),
(7272467, 1131969, 13077, '<td valign="top">I like it - excellent moody environmental portrait, makes me wonder what she is feeling detached from. Very well composed and good processing.</td>', 'I like it - excellent moody environmental portrait, makes me wonder what she is feeling detached from. Very well composed and good processing.', '2014-10-11 22:04:47.000000', NULL, 1),
(7272468, 1131950, 13077, '<td valign="top">Just beautiful. I would point out that most of odriew''s work includes a human element, but I''m imagining myself strolling though that scene and that''s human enough for me.</td>', 'Just beautiful. I would point out that most of odriew''s work includes a human element, but I''m imagining myself strolling though that scene and that''s human enough for me.', '2014-10-11 22:06:29.000000', NULL, 1),
(7272469, 1131594, 13077, '<td valign="top">This just works.</td>', 'This just works.', '2014-10-11 22:06:49.000000', NULL, 1),
(7272470, 1131703, 50864, '<td valign="top">The processing looks pretty close to some of Odriew''s to me. Very pretty landscape.</td>', 'The processing looks pretty close to some of Odriew''s to me. Very pretty landscape.', '2014-10-11 22:07:07.000000', NULL, 1),
(7272471, 1131665, 13077, '<td valign="top">Fascinating sculpture. Well lit and processed.</td>', 'Fascinating sculpture. Well lit and processed.', '2014-10-11 22:07:20.000000', NULL, 1),
(7272472, 1131970, 13077, '<td valign="top">Excellent composition here - I love the varying poses of the geese and the processing is super cool.</td>', 'Excellent composition here - I love the varying poses of the geese and the processing is super cool.', '2014-10-11 22:07:47.000000', NULL, 1),
(7272473, 1131956, 13077, '<td valign="top">I don''t care for this - not sure if it''s the composition, the angle or what. I think a much wider view of the same would have worked better.</td>', 'I don''t care for this - not sure if it''s the composition, the angle or what. I think a much wider view of the same would have worked better.', '2014-10-11 22:08:44.000000', NULL, 1),
(7272474, 1131592, 13077, '<td valign="top">Interesting - I sort of like that her hand is in front of her face, adds some mystery. The light looks good, but I think the added texture is just too much. Other than that, I like it.</td>', 'Interesting - I sort of like that her hand is in front of her face, adds some mystery. The light looks good, but I think the added texture is just too much. Other than that, I like it.', '2014-10-11 22:09:20.000000', NULL, 1),
(7272475, 1132016, 13077, '<td valign="top">I really like this. Beautiful composition and the grain adds to it.</td>', 'I really like this. Beautiful composition and the grain adds to it.', '2014-10-11 22:09:41.000000', NULL, 1),
(7272477, 1131753, 13077, '<td valign="top">Nicely captured moment, but I think a wider shot might have worked better. Looks like it''s not quite in focus either.</td>', 'Nicely captured moment, but I think a wider shot might have worked better. Looks like it''s not quite in focus either.', '2014-10-11 22:10:21.000000', NULL, 1),
(7272478, 1132030, 50864, '<td valign="top">I seldom see such beautiful drain pipes. Lovely light and sweet simplicity.</td>', 'I seldom see such beautiful drain pipes. Lovely light and sweet simplicity.', '2014-10-11 22:11:18.000000', NULL, 1),
(7272479, 1131965, 13077, '<td valign="top">I like the contrast between the vibrant, living plant and the stark, uniform bricks. Well composed, and good processing including the tilt/shift effect.</td>', 'I like the contrast between the vibrant, living plant and the stark, uniform bricks. Well composed, and good processing including the tilt/shift effect.', '2014-10-11 22:11:29.000000', NULL, 1),
(7272480, 1131935, 13077, '<td valign="top">I like the atmosphere and the processing, but the top left part of the background seems distracting. I get the feeling that what lay to the right of the little girl might have worked better?</td>', 'I like the atmosphere and the processing, but the top left part of the background seems distracting. I get the feeling that what lay to the right of the little girl might have worked better?', '2014-10-11 22:12:20.000000', NULL, 1),
(7272481, 1131937, 13077, '<td valign="top">Very cool - I like that the bird is the lightest thing in the frame, and the reflected trees with all the grittiness are very attractive.</td>', 'Very cool - I like that the bird is the lightest thing in the frame, and the reflected trees with all the grittiness are very attractive.', '2014-10-11 22:12:57.000000', NULL, 1),
(7272482, 1131953, 13077, '<td valign="top">Oh, this is really cool. Love the composition, love the colors, love the fact that they all have similar shades of hair except the littlest one.</td>', 'Oh, this is really cool. Love the composition, love the colors, love the fact that they all have similar shades of hair except the littlest one.', '2014-10-11 22:13:32.000000', NULL, 1),
(7272483, 1131848, 13077, '<td valign="top">Beautiful scene, well composed and very good processing.</td>', 'Beautiful scene, well composed and very good processing.', '2014-10-11 22:15:08.000000', NULL, 1),
(7272484, 1131736, 13077, '<td valign="top">Excellent scene, I like the human element of the man with the buckets. Wonderful light, and very well processed.</td>', 'Excellent scene, I like the human element of the man with the buckets. Wonderful light, and very well processed.', '2014-10-11 22:15:39.000000', NULL, 1),
(7272485, 1132031, 13077, '<td valign="top">I like it. Good angle of view, and the varying surfaces and shapes/patterns are cool.</td>', 'I like it. Good angle of view, and the varying surfaces and shapes/patterns are cool.', '2014-10-11 22:16:17.000000', NULL, 1),
(7272486, 1131508, 50864, '<td valign="top">I have to give this a 10 since I think it is the real deal-not a forgery. If it is not Odriew''s you deserve an 11. Beautiful.</td>', 'I have to give this a 10 since I think it is the real deal-not a forgery. If it is not Odriew''s you deserve an 11. Beautiful.', '2014-10-11 22:18:14.000000', NULL, 1),
(7272487, 1132035, 13077, '<td valign="top">I''m not crazy about the composition of this one, or the processing really. In my opinion, exposing for the light parts would have brought out the detail that would be the strength of this scene.</td>', 'I''m not crazy about the composition of this one, or the processing really. In my opinion, exposing for the light parts would have brought out the detail that would be the strength of this scene.', '2014-10-11 22:18:18.000000', NULL, 1),
(7272488, 1131726, 13077, '<td valign="top">I like the shapes and patterns, but not crazy about the tones - it''s mostly a bright green color and not the most pleasing to the eyes in my opinion.</td>', 'I like the shapes and patterns, but not crazy about the tones - it''s mostly a bright green color and not the most pleasing to the eyes in my opinion.', '2014-10-11 22:19:01.000000', NULL, 1),
(7272489, 1131834, 13077, '<td valign="top">I like the softness in contrast to the hard, diagonal shapes of the birds-of-paradise, but I think a different crop or positioning could have improved the composition. Also, there seems to be some kind of pattern overlay in the out-of-focus areas that I''m not fond of.</td>', 'I like the softness in contrast to the hard, diagonal shapes of the birds-of-paradise, but I think a different crop or positioning could have improved the composition. Also, there seems to be some kind of pattern overlay in the out-of-focus areas that I''m not fond of.', '2014-10-11 22:20:07.000000', NULL, 1),
(7272490, 1131923, 13077, '<td valign="top">Nice title. I like the photo - pretty scene, good processing but not crazy about the added texture, it''s very visible on the leftmost part of the image.</td>', 'Nice title. I like the photo - pretty scene, good processing but not crazy about the added texture, it''s very visible on the leftmost part of the image.', '2014-10-11 22:20:54.000000', NULL, 1),
(7272491, 1131997, 13077, '<td valign="top">Is that Albuquerque? Wish I had made it this year. <br/>Nice hazy light here, but I''m not super fond of how the balloon at the far right is cropped in half.</td>', 'Is that Albuquerque? Wish I had made it this year. Nice hazy light here, but I''m not super fond of how the balloon at the far right is cropped in half.', '2014-10-11 22:23:34.000000', NULL, 1),
