(7272578, 1131912, 13077, '<td valign="top">I like the slight human element you''ve included here, but I''m not crazy about the crop/composition.</td>', 'I like the slight human element you''ve included here, but I''m not crazy about the crop/composition.', '2014-10-12 00:44:21.000000', NULL, 1),
(7272603, 1131968, 75618, '<td valign="top">The color palette is nice, I just find the processing and vignette a little overdone.</td>', 'The color palette is nice, I just find the processing and vignette a little overdone.', '2014-10-12 05:40:42.000000', NULL, 1),
(7272604, 1131998, 75618, '<td valign="top">The natural framing is nice but nothing in the image grabs my attention and the processing is not visually appealing to me, sorry.</td>', 'The natural framing is nice but nothing in the image grabs my attention and the processing is not visually appealing to me, sorry.', '2014-10-12 05:50:56.000000', NULL, 1),
