(7272606, 1131689, 75618, '<td valign="top">On their way to Emerald City! Clever composition, couldn''t have positioned your subjects any better.  7</td>', 'On their way to Emerald City! Clever composition, couldn''t have positioned your subjects any better.  7', '2014-10-12 06:00:29.000000', NULL, 1),
