(7272608, 1131995, 75618, '<td valign="top">Very bold, I just think I lack the imagination to fully appreciate abstract photographs like this.</td>', 'Very bold, I just think I lack the imagination to fully appreciate abstract photographs like this.', '2014-10-12 06:05:45.000000', NULL, 1),
(7272610, 1131938, 75618, '<td valign="top">I wish you utilized the full 800 pixels so we can appreciate this better but I do like the chaos. A hodge-podge of memories.</td>', 'I wish you utilized the full 800 pixels so we can appreciate this better but I do like the chaos. A hodge-podge of memories.', '2014-10-12 06:16:37.000000', NULL, 1),
(7272613, 1131791, 75618, '<td valign="top">The simplicity and bareness of this is a breath of fresh air.  7</td>', 'The simplicity and bareness of this is a breath of fresh air.  7', '2014-10-12 06:36:40.000000', NULL, 1),
(7272614, 1131736, 103032, '<td valign="top">Not that I know odriew''s style, but I think this image is the closest of the pack that is in his style.  I find this to be serene.  The fisherman in the bottom right is not the central focus of the photo, but he adds context to the scene.  Without him, there would not be a story to the image.  That''s how I find odriew''s style; there is a figure that adds context and is integral to the photo, but not central...<br/> <br/>On a side note, if this was processed differently, I would have to say this has earmarks of Cuttooth.  In any case, this is my top pick for this challenge.</td>', 'Not that I know odriew''s style, but I think this image is the closest of the pack that is in his style.  I find this to be serene.  The fisherman in the bottom right is not the central focus of the photo, but he adds context to the scene.  Without him, there would not be a story to the image.  That''s how I find odriew''s style; there is a figure that adds context and is integral to the photo, but not central... On a side note, if this was processed differently, I would have to say this has earmarks of Cuttooth.  In any case, this is my top pick for this challenge.', '2014-10-12 07:24:05.000000', NULL, 1),
(7272617, 1131857, 117474, '<td valign="top">Could have been taken one hundred years ago. Fantastic.</td>', 'Could have been taken one hundred years ago. Fantastic.', '2014-10-12 07:55:47.000000', NULL, 1),
(7272618, 1131995, 117474, '<td valign="top">I like this. We all invent our story for this image.</td>', 'I like this. We all invent our story for this image.', '2014-10-12 08:04:49.000000', NULL, 1),
