(7273314, 1131819, 100393, '<td valign="top">Loads to look at - I love the cropped head. Have we seen her before I wonder? The highlight handling is excellent and the lightened shadows fit the style really well - as does the overall motif.</td>', 'Loads to look at - I love the cropped head. Have we seen her before I wonder? The highlight handling is excellent and the lightened shadows fit the style really well - as does the overall motif.', '2014-10-13 20:06:02.000000', NULL, 1),
(7273315, 1132017, 100393, '<td valign="top">Great feel - I love the disciplined and restrictive crop. Great toning too.</td>', 'Great feel - I love the disciplined and restrictive crop. Great toning too.', '2014-10-13 20:06:33.000000', NULL, 1),
(7273316, 1131933, 100393, '<td valign="top">Splendiferous! Bumping to an 8.<br/> <br/>Great muted colours and a super, well-matched texture.</td>', 'Splendiferous! Bumping to an 8. Great muted colours and a super, well-matched texture.', '2014-10-13 20:07:22.000000', NULL, 1),
(7273317, 1131947, 100393, '<td valign="top">Wow - intriguing and delightful. A marvel of curiosities and a look that is certainly towards the challenge style. Bumping to an 8.</td>', 'Wow - intriguing and delightful. A marvel of curiosities and a look that is certainly towards the challenge style. Bumping to an 8.', '2014-10-13 20:08:20.000000', NULL, 1),
