(7273319, 1131856, 100393, '<td valign="top">This is very well crafted.</td>', 'This is very well crafted.', '2014-10-13 20:08:57.000000', NULL, 1),
(7273320, 1132038, 100393, '<td valign="top">Very nice indeed - everything in the image supports everything else.</td>', 'Very nice indeed - everything in the image supports everything else.', '2014-10-13 20:09:25.000000', NULL, 1),
(7273321, 1131713, 100393, '<td valign="top">This conveys fun and life. Well done.</td>', 'This conveys fun and life. Well done.', '2014-10-13 20:10:18.000000', NULL, 1),
(7273322, 1131703, 100393, '<td valign="top">Perhaps a bit extreme in its rendering for my taste but I can certainly see the influence. A healthy 7 from me (voted earlier).</td>', 'Perhaps a bit extreme in its rendering for my taste but I can certainly see the influence. A healthy 7 from me (voted earlier).', '2014-10-13 20:11:10.000000', NULL, 1),
(7273323, 1131970, 100393, '<td valign="top">Like a lounge wall - I like the outdoor/indoor feel - the texture lends a notion of wallpaper. Very pretty image.</td>', 'Like a lounge wall - I like the outdoor/indoor feel - the texture lends a notion of wallpaper. Very pretty image.', '2014-10-13 20:12:08.000000', NULL, 1),
(7273324, 1131503, 100393, '<td valign="top">Oh yes, this really fits. Highly effective. Bumping to an 8.</td>', 'Oh yes, this really fits. Highly effective. Bumping to an 8.', '2014-10-13 20:12:34.000000', NULL, 1),
(7273325, 1131992, 100393, '<td valign="top">Bold and precise with a little ambiguity thrown in. I can see the influence but feel you could have ''dialled it up'' a bit. A healthy 7 nonetheless.</td>', 'Bold and precise with a little ambiguity thrown in. I can see the influence but feel you could have ''dialled it up'' a bit. A healthy 7 nonetheless.', '2014-10-13 20:13:41.000000', NULL, 1),
(7273362, 1131714, 68503, '<td valign="top">I could see this matching his style, nice job.</td>', 'I could see this matching his style, nice job.', '2014-10-14 00:05:33.000000', NULL, 1),
(7273364, 1132018, 68503, '<td valign="top">I like the shot I just think it may be a little to saturated and bright. Maybe a little more muted would have matched it a little better. Still a nice shot though.</td>', 'I like the shot I just think it may be a little to saturated and bright. Maybe a little more muted would have matched it a little better. Still a nice shot though.', '2014-10-14 00:06:44.000000', NULL, 1),
(7273365, 1131753, 68503, '<td valign="top">cute couple and nice candid, just not sure the style is quite there...doesnt matter though because I like it and Im the voter :)</td>', 'cute couple and nice candid, just not sure the style is quite there...doesnt matter though because I like it and Im the voter :)', '2014-10-14 00:08:37.000000', NULL, 1),
(7273367, 1131924, 68503, '<td valign="top">great shot and lighting...processing isnt too far off from his style and I like it, nice job</td>', 'great shot and lighting...processing isnt too far off from his style and I like it, nice job', '2014-10-14 00:11:01.000000', NULL, 1),
(7273376, 1131890, 68503, '<td valign="top">this is a really cool image even though Im not sure it meets the style. Im going to take a stab at guessing how this was done. All the lights off, open shutter, expose with flash, cover the lens and then lightly expose for model?? Either way will be interested to see how it was done.</td>', 'this is a really cool image even though Im not sure it meets the style. Im going to take a stab at guessing how this was done. All the lights off, open shutter, expose with flash, cover the lens and then lightly expose for model?? Either way will be interested to see how it was done.', '2014-10-14 00:58:02.000000', NULL, 1),
(7273377, 1131923, 75618, '<td valign="top">The colors and light are nice, could be from the pages of an old fashion magazine. Vintage vogue. 7</td>', 'The colors and light are nice, could be from the pages of an old fashion magazine. Vintage vogue. 7', '2014-10-14 01:02:59.000000', NULL, 1),
(7273381, 1131987, 75618, '<td valign="top">The simple joys of childhood! I really like how this was composed, especially with the double takes and that little peek of another kid in the corner. 9</td>', 'The simple joys of childhood! I really like how this was composed, especially with the double takes and that little peek of another kid in the corner. 9', '2014-10-14 01:27:23.000000', NULL, 1),
(7273382, 1132038, 75618, '<td valign="top">The tendril is reaching, yearning for light. Delicate and beautiful. 7</td>', 'The tendril is reaching, yearning for light. Delicate and beautiful. 7', '2014-10-14 01:31:47.000000', NULL, 1),
(7273383, 1131970, 75618, '<td valign="top">This exudes so much joy and magic.  I really love the vignetting and texture overlay, makes it look as if I''m witnessing the scene through a grungy old window.  Bumping to 9</td>', 'This exudes so much joy and magic.  I really love the vignetting and texture overlay, makes it look as if I''m witnessing the scene through a grungy old window.  Bumping to 9', '2014-10-14 01:32:29.000000', NULL, 1),
(7273384, 1131594, 75618, '<td valign="top">Wonderful flare! It''s a competent shot but I just don''t find the subject very interesting.</td>', 'Wonderful flare! It''s a competent shot but I just don''t find the subject very interesting.', '2014-10-14 01:39:13.000000', NULL, 1),
(7273385, 1132036, 75618, '<td valign="top">I don''t know if the wonderfully shaped mOOn is intentional but, Thank you.</td>', 'I don''t know if the wonderfully shaped mOOn is intentional but, Thank you.', '2014-10-14 01:41:27.000000', NULL, 1),
(7273386, 1132020, 75618, '<td valign="top">Nice lush foliage but the hue/saturation needs to be dialed down a notch.</td>', 'Nice lush foliage but the hue/saturation needs to be dialed down a notch.', '2014-10-14 01:43:37.000000', NULL, 1),
(7273389, 1132026, 75618, '<td valign="top">It''s really hard to please everybody with a blurry abstract shot. I just don''t find it very engaging/interesting but it is by no means a reflection of any shortcomings on your part.</td>', 'It''s really hard to please everybody with a blurry abstract shot. I just don''t find it very engaging/interesting but it is by no means a reflection of any shortcomings on your part.', '2014-10-14 01:49:57.000000', NULL, 1),
